// src/pages/HomePage.jsx
import React from "react";
import { motion } from "framer-motion";
import { Leaf, Box, BarChart3, Cpu, Recycle } from "lucide-react";
import { Link } from "react-router-dom";
import AboutSection from "../components/AboutSection";
import Footer from "../components/Footer";

const HomePage = () => {
  return (
    <div className="bg-gradient-to-b from-green-50 via-white to-green-100 min-h-screen text-gray-800">
      {/* 🌿 Navbar */}
      <nav className="flex justify-between items-center p-6 bg-white shadow-md sticky top-0 z-50">
        <h1 className="text-2xl font-extrabold text-green-700 tracking-wide">
          EcoPack<span className="text-green-500">AI</span>
        </h1>
        <div className="space-x-6">
          <Link to="/login" className="text-gray-700 hover:text-green-700">Login</Link>
          <Link to="/register" className="text-gray-700 hover:text-green-700">Sign Up</Link>
          <Link to="/about" className="text-gray-700 hover:text-green-700">About</Link>
        </div>
      </nav>

      {/* 🌎 Hero Section */}
      <section className="flex flex-col md:flex-row justify-between items-center px-8 md:px-20 py-20 md:py-28">
        {/* Left text content */}
        <motion.div
          initial={{ opacity: 0, x: -60 }}
          animate={{ opacity: 1, x: 0 }}
          transition={{ duration: 0.8 }}
          className="md:w-1/2 space-y-6"
        >
          <h2 className="text-4xl md:text-6xl font-bold text-green-800 leading-tight">
            Smarter Packaging for a <br /> <span className="text-green-600">Sustainable Future</span>
          </h2>
          <p className="text-gray-700 text-lg">
            EcoPackAI uses artificial intelligence to recommend eco-friendly, cost-effective, and 
            durable packaging materials — reducing your carbon footprint one package at a time.
          </p>
          <div className="space-x-4">
            <Link
              to="/register"
              className="bg-green-600 text-white px-6 py-3 rounded-xl shadow-md hover:bg-green-700"
            >
              Get Started
            </Link>
            <Link
              to="/demo"
              className="border border-green-600 text-green-700 px-6 py-3 rounded-xl hover:bg-green-50"
            >
              Try Demo
            </Link>
          </div>
        </motion.div>

        {/* Right hero image */}
        <motion.div
          initial={{ opacity: 0, x: 60 }}
          animate={{ opacity: 1, x: 0 }}
          transition={{ duration: 0.9 }}
          className="md:w-1/2 flex justify-center mt-10 md:mt-0"
        >
          <img
            src="https://cdn-icons-png.flaticon.com/512/7774/7774345.png"
            alt="Eco Packaging"
            className="w-80 md:w-96 drop-shadow-lg"
          />
        </motion.div>
      </section>

      {/* 💡 Features Section */}
      <section className="py-20 bg-white text-center">
        <motion.h3
          initial={{ opacity: 0, y: 40 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.6 }}
          className="text-3xl md:text-4xl font-bold text-green-800 mb-10"
        >
          What Makes EcoPackAI Unique?
        </motion.h3>

        <div className="grid grid-cols-1 md:grid-cols-3 gap-10 max-w-6xl mx-auto px-8">
          {[
            {
              icon: <Cpu className="w-10 h-10 text-green-600 mx-auto mb-4" />,
              title: "AI-Powered Recommendations",
              desc: "Smart algorithms suggest optimal eco-friendly packaging materials for your products."
            },
            {
              icon: <BarChart3 className="w-10 h-10 text-green-600 mx-auto mb-4" />,
              title: "Cost & CO₂ Analysis",
              desc: "Instantly compare materials based on cost efficiency and environmental impact."
            },
            {
              icon: <Box className="w-10 h-10 text-green-600 mx-auto mb-4" />,
              title: "Smart Packaging Database",
              desc: "Access verified data for 20+ sustainable materials and their global suppliers."
            }
          ].map((item, i) => (
            <motion.div
              key={i}
              initial={{ opacity: 0, y: 40 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: i * 0.2, duration: 0.5 }}
              className="bg-green-50 hover:bg-green-100 transition-all p-8 rounded-2xl shadow-lg"
            >
              {item.icon}
              <h4 className="text-xl font-semibold mb-3">{item.title}</h4>
              <p className="text-gray-700">{item.desc}</p>
            </motion.div>
          ))}
        </div>
      </section>

      {/* 🌱 Sustainability Impact */}
      <section className="py-24 bg-gradient-to-r from-green-700 to-green-500 text-white text-center">
        <motion.h3
          initial={{ opacity: 0, y: 30 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.6 }}
          className="text-3xl font-bold mb-6"
        >
          Every Choice Counts 🌍
        </motion.h3>
        <p className="max-w-3xl mx-auto text-lg mb-10">
          Together, we can transform the packaging industry. Each AI-driven
          recommendation contributes to lowering global carbon emissions and
          reducing plastic waste.
        </p>
        <div className="flex flex-wrap justify-center gap-8">
          <div className="bg-white text-green-700 font-bold text-xl px-10 py-6 rounded-2xl shadow-lg">
            ♻️ 30% Less CO₂ Emission
          </div>
          <div className="bg-white text-green-700 font-bold text-xl px-10 py-6 rounded-2xl shadow-lg">
            🌿 100% Sustainable Materials
          </div>
          <div className="bg-white text-green-700 font-bold text-xl px-10 py-6 rounded-2xl shadow-lg">
            🌎 Global Impact Analytics
          </div>
        </div>
      </section>

      {/* 🧩 About Section */}
      <AboutSection />

      {/* 🌿 Footer */}
      <Footer />
    </div>
  );
};

export default HomePage;
